import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-09-09","description":"2026-09-09 Agent 核心研究者、协议与 Runtime 项目、CodeFlowMu 竞品雷达的双源监测结果。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-09-09","description":"2026-09-09 Agent 核心研究者、协议与 Runtime 项目、CodeFlowMu 竞品雷达的双源监测结果。","outline":"deep"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-09-09.md","filePath":"zh/runtime/daily-intelligence/2026-09-09.md","lastUpdated":1788921187000}'),n={name:"zh/runtime/daily-intelligence/2026-09-09.md"};function i(s,e,l,p,c,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="agent-核心研究与竞品动态-·-2026-09-09" tabindex="-1">Agent 核心研究与竞品动态 · 2026-09-09 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-09-09" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-09-09&quot;">​</a></h1><blockquote><p>仅记录 meaningful new developments。来源优先采用本人、官方项目、GitHub PR/Issue/Release 与一手工程资料；不以 star 数、营销转发或无技术增量的小版本凑数。</p></blockquote><h2 id="今日结论" tabindex="-1">今日结论 <a class="header-anchor" href="#今日结论" aria-label="Permalink to &quot;今日结论&quot;">​</a></h2><p>本轮最强的共同趋势是：<strong>Agent Runtime 正把最后一次安全检查不断推近真实副作用边界，同时把能力声明、执行所有权、操作语义和恢复事实拆成可验证合同。</strong> 对 CodeFlowMu/FCoP 来说，执行链更适合明确为：</p><p><strong>Capability Grant → Admission Decision → Effect Preconditions → Call-time Authority → Effect Receipt → Evidence-driven Settlement</strong>。</p><h2 id="_1-openai-codex-单写者会话、pid-绑定的进程控制与真人验证能力边界" tabindex="-1">1. OpenAI Codex：单写者会话、PID 绑定的进程控制与真人验证能力边界 <a class="header-anchor" href="#_1-openai-codex-单写者会话、pid-绑定的进程控制与真人验证能力边界" aria-label="Permalink to &quot;1. OpenAI Codex：单写者会话、PID 绑定的进程控制与真人验证能力边界&quot;">​</a></h2><p>Codex 正在把 Conversation ownership、Process control 与 Human verification 做成独立控制面。PR #43253 规定同一 conversation 只允许一个 active writer；新的 resume 在 writer 已存在时降级为只读历史视图，不再抢写。PR #43308 则让 Windows managed app-server 的 shutdown 通过本地 control socket 请求，并要求 PID 匹配后才进入 drain；错误 PID 或非受管启动会拒绝。PR #43289 新增 MCP <code>openai/userVerification</code> 协议处理，但 capability 仍受 Host 控制，未声明支持的 client 不能使用。</p><p><strong>为什么重要：</strong> <code>Running</code> 不足以表示执行权。生产级 Runtime 需要区分 Writer Lease、Observer Access、Host Process Identity 和 Human Verification Receipt。</p><p><strong>互动切入：</strong> <em>Will user-verification proofs eventually be bound to the active writer/authority epoch, so a proof obtained by one conversation owner cannot survive a writer handoff?</em></p><p>来源：</p><ul><li><a href="https://github.com/openai/codex/pull/43253" target="_blank" rel="noreferrer">Codex PR #43253</a></li><li><a href="https://github.com/openai/codex/pull/43308" target="_blank" rel="noreferrer">Codex PR #43308</a></li><li><a href="https://github.com/openai/codex/pull/43289" target="_blank" rel="noreferrer">Codex PR #43289</a></li></ul><h2 id="_2-openai-agents-sdk-工具名称不能代替真实-effect-semantics" tabindex="-1">2. OpenAI Agents SDK：工具名称不能代替真实 effect semantics <a class="header-anchor" href="#_2-openai-agents-sdk-工具名称不能代替真实-effect-semantics" aria-label="Permalink to &quot;2. OpenAI Agents SDK：工具名称不能代替真实 effect semantics&quot;">​</a></h2><p>两个新安全问题都说明工具表面语义可能比真实副作用更窄。PR #4893 指出 <code>apply_patch</code> 的 <code>*** Add File:</code> 在目标已存在时可能静默覆盖，却仍向模型报告 Created；拟议修复要求 create-only 行为必须证明目标不存在。PR #4894 则发现 sandbox S3 Files mount 的逗号拼接参数可被输入值注入额外 mount option；拟议修复是在进入 <code>mount -o</code> 之前拒绝 delimiter injection。</p><p><strong>为什么重要：</strong> Authorization 不能只看 tool name。真正需要进入授权合同的是 normalized effect class，例如 create-only、overwrite、mount-policy mutation。</p><p><strong>状态：</strong> 两条 PR 均仍 OPEN，尚不能视为正式发布能力。</p><p><strong>互动切入：</strong> <em>Would you consider exposing normalized effect classes from sandbox tools, so an authorization layer can distinguish create-only, overwrite, mount-policy mutation and other effects without reverse-engineering tool arguments?</em></p><p>来源：</p><ul><li><a href="https://github.com/openai/openai-agents-python/pull/4893" target="_blank" rel="noreferrer">Agents SDK PR #4893</a></li><li><a href="https://github.com/openai/openai-agents-python/pull/4894" target="_blank" rel="noreferrer">Agents SDK PR #4894</a></li></ul><h2 id="_3-ag2-mcp-apps-引入-app-可调用、模型不可见-的工具主体" tabindex="-1">3. AG2：MCP Apps 引入“App 可调用、模型不可见”的工具主体 <a class="header-anchor" href="#_3-ag2-mcp-apps-引入-app-可调用、模型不可见-的工具主体" aria-label="Permalink to &quot;3. AG2：MCP Apps 引入“App 可调用、模型不可见”的工具主体&quot;">​</a></h2><p>PR #3235 正在加入 MCP Apps (<code>io.modelcontextprotocol/ui</code>) 支持。UI document 作为 Resource 与 Tool 绑定；只有 client 明确声明可渲染 MCP App 时才下发 UI binding。更值得关注的是 <code>visibility=[&quot;app&quot;]</code>：这类 Tool 可以由 App UI 按钮调用，但不暴露给模型。</p><p><strong>为什么重要：</strong> 执行主体不再只有 Model → Tool，还出现 Human → App UI → Tool。App-only tool 需要自己的 principal、user gesture 和 authorization evidence，不能因为“模型看不到”就默认更可信。</p><p><strong>状态：</strong> OPEN，尚未合入。</p><p><strong>互动切入：</strong> <em>For <code>visibility=[&#39;app&#39;]</code> tools, do you plan to expose a distinct invocation principal/user-gesture provenance so audit can distinguish model-selected calls from human UI actions?</em></p><p>来源：</p><ul><li><a href="https://github.com/ag2ai/ag2/pull/3235" target="_blank" rel="noreferrer">AG2 PR #3235</a></li></ul><h2 id="_4-paperclip-pre-start-admission、插件能力升级与恢复分类继续逼近治理-runtime" tabindex="-1">4. Paperclip：pre-start admission、插件能力升级与恢复分类继续逼近治理 Runtime <a class="header-anchor" href="#_4-paperclip-pre-start-admission、插件能力升级与恢复分类继续逼近治理-runtime" aria-label="Permalink to &quot;4. Paperclip：pre-start admission、插件能力升级与恢复分类继续逼近治理 Runtime&quot;">​</a></h2><p>Paperclip 仍是本轮最高竞争优先级之一。PR #12949 正在增加 provider 副作用发生前的 pre-start admission hook：Run 已 claim，但 adapter/native runner/provider 尚未启动时，Host 可依据 issue、run、wake、provider、model 和 capacity snapshot 做最后裁决；Enforce 模式遇到缺失、过期或无效 telemetry 时 fail closed。PR #12928 则处理 Plugin capability escalation：升级新增 capability 不再自动成为既有 grant，而进入 <code>upgrade_pending</code>，等待 operator 明确审批。PR #12946 记录真实部署中的 lease、无限 continuation、错误 success classification 和 cross-issue guard 证据问题。</p><p><strong>为什么重要：</strong> Paperclip 正形成完整链条：Declared Capability → Approved Grant → Pre-start Admission → Run Ownership → Provider Effect → Recovery Classification。</p><p><strong>竞品判断：</strong> 学习价值非常高；竞争风险很高；继续按一线 Runtime 控制面竞品观察。</p><p><strong>状态：</strong> 上述 PR 当前仍 OPEN，不能提前算作正式发布能力。</p><p><strong>互动切入：</strong> <em>Will pre-start admission eventually bind the resulting decision to an authority epoch/effect receipt, so a queued run cannot pass admission and then execute after its telemetry or capability grant has materially changed?</em></p><p>来源：</p><ul><li><a href="https://github.com/paperclipai/paperclip/pull/12949" target="_blank" rel="noreferrer">Paperclip PR #12949</a></li><li><a href="https://github.com/paperclipai/paperclip/pull/12928" target="_blank" rel="noreferrer">Paperclip PR #12928</a></li><li><a href="https://github.com/paperclipai/paperclip/pull/12946" target="_blank" rel="noreferrer">Paperclip PR #12946</a></li></ul><h2 id="_5-github-mcp-server-精确补丁写入开始要求-前置事实证明" tabindex="-1">5. GitHub MCP Server：精确补丁写入开始要求“前置事实证明” <a class="header-anchor" href="#_5-github-mcp-server-精确补丁写入开始要求-前置事实证明" aria-label="Permalink to &quot;5. GitHub MCP Server：精确补丁写入开始要求“前置事实证明”&quot;">​</a></h2><p>Draft PR #3232 新增 <code>apply_file_patch</code>，要求调用方同时提供 exact <code>expected_head_sha</code> 和 exact <code>expected_blob_sha</code>；<code>old_text</code> 必须精确出现预期次数，禁止 fuzzy matching、offset guessing、空匹配、no-op、symlink、非 UTF-8 和过大 patch，branch 更新也使用 <code>force=false</code>，并发变化会以 non-fast-forward 失败。</p><p><strong>为什么重要：</strong> 写文件不再只是“执行一个命令”，而是明确声明：我预计 Branch 仍是 X、File 仍是 Y，只有两项前置事实都成立才允许产生 Z。对 FCoP 4.0 的并发线性化、幂等和 effect precondition 很有参考价值。</p><p><strong>状态：</strong> DRAFT，尚未合入。</p><p><strong>互动切入：</strong> <em>Would you consider returning a durable effect receipt containing expected head/blob and resulting commit/blob, making the exact precondition-to-effect transition directly auditable by agent runtimes?</em></p><p>来源：</p><ul><li><a href="https://github.com/github/github-mcp-server/pull/3232" target="_blank" rel="noreferrer">GitHub MCP Server PR #3232</a></li></ul><h2 id="_6-orca-unknown-由后续正证据收敛-pid-与-lease-不再被当作死亡事实" tabindex="-1">6. Orca：Unknown 由后续正证据收敛，PID 与 lease 不再被当作死亡事实 <a class="header-anchor" href="#_6-orca-unknown-由后续正证据收敛-pid-与-lease-不再被当作死亡事实" aria-label="Permalink to &quot;6. Orca：Unknown 由后续正证据收敛，PID 与 lease 不再被当作死亡事实&quot;">​</a></h2><p>已合入的 PR #19140 修复 Structured Claude Chat 的 delivery journal：消息初始可能被标成 <code>unknown</code>，但 provider 后续 echo 到达后，会根据原 <code>clientMessageId</code> 将同一 durable submission 推进为 <code>accepted</code>，不会产生第二次 dispatch。两个仍 OPEN 的后续 PR 则继续收紧 Windows Runtime：#19149 将 PID 与 creation-time ordering 一起作为 process ancestry evidence，避免 PID reuse 把无关进程误判为 descendant；#19155 明确 lease expiry 不能证明 owner 已死，只有 provider root 的正死亡证据和已知 descendant 状态才能驱动 lease release。</p><p><strong>为什么重要：</strong> Unknown 可以被正证据收敛，但 timeout、lease expiry 和“没看到进程”不能自行升级成事实。</p><p><strong>竞品判断：</strong> Orca 的 long-running、Windows 与 recovery 权重继续上调。</p><p><strong>互动切入：</strong> <em>Do you plan to converge message-delivery identity and process/lease evidence onto one general evidence-transition model, where <code>unknown → accepted/dead</code> requires a named positive observation rather than timeout-derived inference?</em></p><p>来源：</p><ul><li><a href="https://github.com/stablyai/orca/pull/19140" target="_blank" rel="noreferrer">Orca PR #19140</a></li><li><a href="https://github.com/stablyai/orca/pull/19149" target="_blank" rel="noreferrer">Orca PR #19149</a></li><li><a href="https://github.com/stablyai/orca/pull/19155" target="_blank" rel="noreferrer">Orca PR #19155</a></li></ul><h2 id="跨项目判断" tabindex="-1">跨项目判断 <a class="header-anchor" href="#跨项目判断" aria-label="Permalink to &quot;跨项目判断&quot;">​</a></h2><p>今天的共同方向可以压缩成一句话：</p><blockquote><p><strong>真正安全的 Agent 不是“先判断一次，然后长期相信”，而是在距离副作用越来越近的地方不断重新证明：对象还是那个对象、能力还是那份能力、Owner 还是那个 Owner、前置事实还成立。</strong></p></blockquote><p>这进一步支持 CodeFlowMu/FCoP 将执行链拆成六个不可互换的阶段：</p><ol><li><strong>Capability Grant</strong> — 当前主体被授予什么能力；</li><li><strong>Admission Decision</strong> — 本轮任务是否允许进入执行；</li><li><strong>Effect Preconditions</strong> — 真实副作用前的事实前提是否仍成立；</li><li><strong>Call-time Authority</strong> — 到真正执行时权限是否仍有效；</li><li><strong>Effect Receipt</strong> — 实际做了什么、依据什么；</li><li><strong>Evidence-driven Settlement</strong> — 成功、失败或 unknown 只能由明确证据收敛。</li></ol><hr><p><strong>监测范围：</strong> 41 位核心人物 + OpenAI/Cursor/MCP/AG2/OpenHands/CrewAI 等项目级信号 + CodeFlowMu 31 个竞品雷达。<br><strong>双源原则：</strong> GitHub/官方工程资料 + 可可靠确认的 X/公开社交来源。<br><strong>本轮社交侧：</strong> 未发现技术增量高于上述一手工程材料、且身份与时间均可可靠确认的新本人讨论，因此未使用营销转发补数。</p>',54)])])}const h=t(n,[["render",i]]);export{g as __pageData,h as default};
